describe('User Mention in Comments', () => {
  beforeEach(() => {
    cy.visit('/comments');
  });

  it('should successfully mention another user in a comment', () => {
    // Intercept the API call to create a comment
    cy.intercept('POST', '/api/comments').as('createComment');

    // Get the comment form
    cy.get('[data-testid="comment-form"]').should('be.visible');

    // Fill in the comment form
    cy.get('[data-testid="comment-input"]').type('This is a great article!');

    // Find the user to mention
    cy.get('[data-testid="mention-user-input"]').click();
    cy.get('[data-testid="mention-user-dropdown"]').click();
    cy.get('[data-testid="mention-user-option"]').click({ force: true });
    cy.get('[data-testid="mention-user-name-input"]').type('@john_doe');

    // Submit the comment
    cy.get('[data-testid="comment-submit-button"]').click();

    // Verify the comment was created
    cy.wait('@createComment').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify the comment contains the mention
    cy.get('[data-testid="comment-list"]').should('contain', '@john_doe');

    // Verify the mention appears in the comment
    cy.get('[data-testid="comment-item"]').first().should('contain', '@john_doe');
  });

  it('should handle mentioning a non-existent user gracefully', () => {
    // Intercept the API call to create a comment
    cy.intercept('POST', '/api/comments').as('createComment');

    // Get the comment form
    cy.get('[data-testid="comment-form"]').should('be.visible');

    // Fill in the comment form
    cy.get('[data-testid="comment-input"]').type('This is a great article!');

    // Attempt to mention a non-existent user
    cy.get('[data-testid="mention-user-input"]').click();
    cy.get('[data-testid="mention-user-dropdown"]').click();
    cy.get('[data-testid="mention-user-option"]').click({ force: true });
    cy.get('[data-testid="mention-user-name-input"]').type('@nonexistent_user');

    // Submit the comment
    cy.get('[data-testid="comment-submit-button"]').click();

    // Verify the comment was created without the mention
    cy.wait('@createComment').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify the comment does not contain the mention
    cy.get('[data-testid="comment-list"]').should('not.contain', '@nonexistent_user');

    // Verify the user is notified about the failed mention
    cy.get('[data-testid="mention-error-message"]').should('be.visible');
    cy.get('[data-testid="mention-error-message"]').should('contain', 'User not found');
  });
});
